  `merchant_id` bigint unsigned NOT NULL COMMENT '商家ID',
  `title` varchar(100) NOT NULL COMMENT '券标题',
  `sub_title` varchar(255) DEFAULT NULL COMMENT '副标题/描述',
  `image_url` varchar(255) DEFAULT NULL,
